changeSet.sql:
INSERT INTO m_kyc_case_flag (kyc_case_id, kyc_flag_type_id, status_enum, created_date) SELECT kc.id, ft.id, 100, CURRENT_TIMESTAMP FROM m_kyc_case kc CROSS JOIN m_kyc_flag_type ft WHERE kc.risk_flags LIKE '%EXPIRING_SOON%' AND ft.code = 'EXPIRING_SOON';
INSERT INTO m_kyc_case_flag (kyc_case_id, kyc_flag_type_id, status_enum, created_date) SELECT kc.id, ft.id, 100, CURRENT_TIMESTAMP FROM m_kyc_case kc CROSS JOIN m_kyc_flag_type ft WHERE kc.risk_flags LIKE '%PERIODIC_REVIEW_DUE%' AND ft.code = 'PERIODIC_REVIEW_DUE';
